CREATE TABLE IF NOT EXISTS products (id SERIAL PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL,price NUMERIC(10,2) NOT NULL CHECK(price>=0),stock INTEGER NOT NULL CHECK(stock>=0));
CREATE TABLE IF NOT EXISTS orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),customer_name TEXT NOT NULL,total NUMERIC(12,2) NOT NULL CHECK(total>=0),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items (id SERIAL PRIMARY KEY,order_id UUID NOT NULL REFERENCES orders(id),product_id INTEGER NOT NULL REFERENCES products(id),product_name TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price NUMERIC(10,2) NOT NULL CHECK(unit_price>=0),UNIQUE(order_id,product_id));
CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'student' CHECK(role IN ('student','admin')),student_id TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,csrf_token TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS pickup_locations(id SERIAL PRIMARY KEY,name TEXT NOT NULL UNIQUE,instructions TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS addresses(id SERIAL PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,label TEXT NOT NULL,address TEXT NOT NULL);
ALTER TABLE products ADD COLUMN IF NOT EXISTS category TEXT NOT NULL DEFAULT 'Stationery';
ALTER TABLE products ADD COLUMN IF NOT EXISTS images JSONB NOT NULL DEFAULT '[]';
ALTER TABLE products ADD COLUMN IF NOT EXISTS specifications JSONB NOT NULL DEFAULT '{}';
ALTER TABLE products ADD COLUMN IF NOT EXISTS active BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE products ADD COLUMN IF NOT EXISTS featured BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS user_id INTEGER REFERENCES users(id);
ALTER TABLE orders ADD COLUMN IF NOT EXISTS pickup_location_id INTEGER REFERENCES pickup_locations(id);
ALTER TABLE orders ADD COLUMN IF NOT EXISTS pickup_name TEXT;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS notes TEXT NOT NULL DEFAULT '';
ALTER TABLE orders ADD COLUMN IF NOT EXISTS status TEXT NOT NULL DEFAULT 'placed';
ALTER TABLE orders ADD COLUMN IF NOT EXISTS request_key UUID;
CREATE UNIQUE INDEX IF NOT EXISTS order_request_key ON orders(user_id,request_key);
CREATE TABLE IF NOT EXISTS order_events(id SERIAL PRIMARY KEY,order_id UUID NOT NULL REFERENCES orders(id),status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS carts(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,product_id INTEGER NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 100),PRIMARY KEY(user_id,product_id));
CREATE TABLE IF NOT EXISTS wishlists(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,product_id INTEGER NOT NULL REFERENCES products(id),PRIMARY KEY(user_id,product_id));
UPDATE products SET category=CASE WHEN lower(name) LIKE '%backpack%' THEN 'Bags' WHEN lower(name) LIKE '%bottle%' THEN 'Accessories' WHEN lower(name) LIKE '%database%' THEN 'Books' ELSE 'Stationery' END,featured=true WHERE id<=6;
UPDATE products SET specifications='{"Material":"Durable fabric","Use":"Campus commute","Care":"Wipe clean"}' WHERE lower(name) LIKE '%backpack%';
UPDATE products SET specifications='{"Currency":"INR","Collection":"Campus essentials"}' WHERE specifications='{}';
INSERT INTO pickup_locations(name,instructions) VALUES ('Main Campus Store','Collect at the student services building, Monday–Friday, 9am–5pm.'),('Library Collection Desk','Collect at the library entrance desk, Monday–Friday, 10am–4pm.'),('Engineering Block','Collect at the engineering block reception, Monday–Friday, 9am–4pm.') ON CONFLICT(name) DO NOTHING;
INSERT INTO order_events(order_id,status) SELECT id,status FROM orders o WHERE NOT EXISTS(SELECT 1 FROM order_events e WHERE e.order_id=o.id);
